// All good. Now store iconURL for future usage.
const pageURI = Services.io.newURI(feedURL);
const iconURI = Services.io.newURI(iconURL);
const dataURL = await lazy.MailUtils.getFaviconDataURLFromNetwork(iconURI);
try {
  await lazy.PlacesUtils.favicons.setFaviconForPage(
    pageURI,
    iconURI,
    dataURL
  );
} catch (e) {
  // Likely image corrupt or truncated.
  this.log.warn(`Discovered bad favicon for ${url}`, e);
  return "";
}

const favicon = await lazy.PlacesUtils.favicons.getFaviconForPage(pageURI);
return favicon?.dataURI.spec;

const callback = iconUrl => {
  item.favicon = iconUrl;
  if (item.folder) {
    for (const child of item.children) {
      if (!child.container) {
        child.favicon = iconUrl;
        break;
      }
    }
  }

  this.selection.tree.invalidateRow(aRow);

  // A feed.
  setTimeout(async () => {
    const iconUrl = await FeedUtils.getFavicon(
      item.parentFolder,
      item.url
    );
    if (iconUrl) {
      callback(iconUrl);
    }
  }, 0);
}

// Store empty string to return default while favicons are retrieved.
return (item.favicon = "");
